    retVal.add((T)next);
  }
  if (next instanceof ICompositeElement) {
    ICompositeElement iCompositeElement=(ICompositeElement)next;
    retVal.addAll(iCompositeElement.getAllPopulatedChildElementsOfType(theType));
  }
}
